function enemySpecies(time,boss=false){const stage=boss?'Mega':time<25?'Rookie':time<50?'Champion':'Ultimate';const pool=run&&run.cast&&run.cast[stage]||SPECIES.filter(s=>s.stage===stage);if(!pool.length)throw new Error('No Digimon for '+stage);return pool[Math.floor(Math.random()*pool.length)];}
function enemyCast(){const cast={};for(const stage of STAGES){const pool=SPECIES.filter(s=>s.stage===stage).sort(()=>Math.random()-.5);if(pool.length)cast[stage]=pool.slice(0,Math.min(3,pool.length));}return cast;}
function enemyBehavior(s){return s.speed>=190?'runner':s.hp>=145?'tank':s.element==='Fire'?'charger':s.element==='Electric'||s.element==='Light'?'ranged':'chase';}
function start(){const s=byId[data.selected],lv=upgradeLevel(s.id);run={time:0,hp:s.hp*(1+.1*lv),maxHp:s.hp*(1+.1*lv),kills:0,spawn:0,shot:0,level:1,xp:0,nextXp:7,damage:s.damage*(1+.05*lv),speed:s.speed,rate:s.rate,projectiles:1,paused:false,ended:false,boss:false,player:{x:400,y:240},enemies:[],shots:[],enemyShots:[],effects:[],enemyId:0,cast:enemyCast(),hit:0};tab='Combate';render();}
function finish(win){if(!run||run.ended)return;run.ended=true;run.paused=false;data.runs++;data.best=Math.max(data.best,run.time);const reward=Math.max(1,Math.floor(run.time/15))+(win?5:0),coins=Math.floor(run.kills/3)+(win?25:0);data.tickets+=reward;data.coins+=coins;save();render();message((win?'¡Victoria!':'Fin de partida')+' · +'+reward+' tickets · +'+coins+' DigiCoins');}
function gainXp(){if(run.paused||run.ended)return;run.xp++;if(run.xp>=run.nextXp){run.xp-=run.nextXp;run.level++;run.nextXp+=5;run.paused=true;const box=$('levelChoices');if(!box){run.paused=false;return;}box.style.display='block';box.innerHTML='<h2>Nivel '+run.level+' · Elige mejora</h2>';for(const [label,fn] of [['+20% daño',()=>run.damage*=1.2],['+15% velocidad',()=>run.speed*=1.15],['+20 HP máximo y curar',()=>{run.maxHp+=20;run.hp=Math.min(run.maxHp,run.hp+30);}],['Ataque más rápido',()=>run.rate*=.88]])box.append(btn(label,()=>{fn();box.style.display='none';run.paused=false;}));}}
function update(dt){if(!run||run.ended||run.paused||tab!=='Combate')return;const r=run,p=r.player;r.time+=dt;r.spawn-=dt;r.shot-=dt;r.hit-=dt;const dx=Number(keys.has('d')||keys.has('arrowright'))-Number(keys.has('a')||keys.has('arrowleft'))+stick.x,dy=Number(keys.has('s')||keys.has('arrowdown'))-Number(keys.has('w')||keys.has('arrowup'))+stick.y,len=Math.max(1,Math.hypot(dx,dy));p.x=Math.max(15,Math.min(785,p.x+dx/len*r.speed*dt));p.y=Math.max(15,Math.min(465,p.y+dy/len*r.speed*dt));if(r.spawn<=0){r.spawn=Math.max(.25,.85-r.time*.004);const side=Math.floor(Math.random()*4),s=enemySpecies(r.time),type=enemyBehavior(s);r.enemies.push({x:side===0?-28:side===1?828:Math.random()*800,y:side===2?-28:side===3?508:Math.random()*480,hp:(2+Math.floor(r.time/35))*(s.hp/110),boss:false,uid:++r.enemyId,slowUntil:0,type,speciesId:s.id,cast:1.5,phase:'walk',phaseTime:0,dashX:0,dashY:0});}
if(!r.boss&&r.time>=65){r.boss=true;r.enemies.push({x:400,y:0,hp:55,boss:true,maxHp:55,uid:++r.enemyId,slowUntil:0,speciesId:enemySpecies(r.time,true).id});}
if(r.shot<=0&&r.enemies.length){r.shot=r.rate;const targets=r.enemies.filter(e=>e.hp>0);if(targets.length){const target=targets.reduce((a,b)=>Math.hypot(p.x-a.x,p.y-a.y)<Math.hypot(p.x-b.x,p.y-b.y)?a:b);const angle=Math.atan2(target.y-p.y,target.x-p.x);for(let i=0;i<r.projectiles;i++){const a=angle+(i-(r.projectiles-1)/2)*.17;r.shots.push({...DigimonCombat.projectile(byId[data.selected].element,r.damage,p.x,p.y,a),color:ELEMENT_COLORS[byId[data.selected].element]||'#ffdc64'});}}}
for(const e of r.enemies){const species=byId[e.speciesId]||byId.agumon;const d=Math.max(1,Math.hypot(e.x-p.x,e.y-p.y)),spd=(e.boss?35:Math.max(30,Math.min(110,species.speed*.48)))*(e.slowUntil>0?.6:1);e.slowUntil=Math.max(0,(e.slowUntil||0)-dt);if(e.type==='charger'&&!e.boss){e.phaseTime-=dt;if(e.phase==='walk'&&d<200&&e.phaseTime<=0){e.phase='aim';e.phaseTime=.55;}if(e.phase==='aim'&&e.phaseTime<=0){e.phase='dash';e.phaseTime=.42;e.dashX=(p.x-e.x)/d;e.dashY=(p.y-e.y)/d;}if(e.phase==='dash'){e.x+=e.dashX*spd*3.4*dt;e.y+=e.dashY*spd*3.4*dt;if(e.phaseTime<=0){e.phase='walk';e.phaseTime=1.1;}}else if(e.phase==='walk'){e.x+=(p.x-e.x)/d*spd*dt;e.y+=(p.y-e.y)/d*spd*dt;}}else if(e.type==='ranged'&&!e.boss){e.cast=(e.cast||0)-dt;if(e.cast<=0){e.cast=2;const a=Math.atan2(p.y-e.y,p.x-e.x);r.enemyShots.push({x:e.x,y:e.y,vx:Math.cos(a)*150,vy:Math.sin(a)*150,ttl:3,damage:Math.max(6,Math.round(species.damage*.55)),color:ELEMENT_COLORS[species.element]||'#fff'});}if(d<170){e.x-=(p.x-e.x)/d*spd*.65*dt;e.y-=(p.y-e.y)/d*spd*.65*dt;}else if(d>220){e.x+=(p.x-e.x)/d*spd*dt;e.y+=(p.y-e.y)/d*spd*dt;}}else if(e.type!=='charger'||e.boss){e.x+=(p.x-e.x)/d*spd*dt;e.y+=(p.y-e.y)/d*spd*dt;}if(d<(e.boss?34:21)&&r.hit<=0){r.hp-=e.boss?Math.max(18,Math.round(species.damage*.65)):Math.max(6,Math.round(species.damage*.6));r.hit=.5;}}
for(const s of r.enemyShots){s.x+=s.vx*dt;s.y+=s.vy*dt;s.ttl-=dt;if(Math.hypot(s.x-p.x,s.y-p.y)<17&&r.hit<=0){r.hp-=s.damage;r.hit=.5;s.ttl=0;}}r.enemyShots=r.enemyShots.filter(s=>s.ttl>0);for(const s of r.shots){s.x+=s.vx*dt;s.y+=s.vy*dt;s.ttl-=dt;for(const e of r.enemies){if(e.hp>0&&Math.hypot(s.x-e.x,s.y-e.y)<(e.boss?33:16)){if(DigimonCombat.applyHit(s,e)){r.effects.push({x:e.x,y:e.y,ttl:.22,color:s.color});if(s.ttl<=0)break;}}}}
const dead=r.enemies.filter(e=>e.hp<=0);r.kills+=dead.length;r.enemies=r.enemies.filter(e=>e.hp>0);r.shots=r.shots.filter(s=>s.ttl>0);for(const fx of r.effects)fx.ttl-=dt;r.effects=r.effects.filter(fx=>fx.ttl>0);for(const e of dead){if(!r.paused)gainXp();else r.xp++;}if(r.hp<=0){r.hp=0;finish(false);}else if(r.boss&&!r.enemies.some(e=>e.boss)){finish(true);}else if(r.time>=90){finish(false);}}
function draw(){if(tab!=='Combate'||!$('game')||!run)return;const ctx=$('game').getContext('2d'),r=run,p=r.player;ctx.clearRect(0,0,800,480);ctx.fillStyle='#25404a';ctx.strokeStyle='#35505a';for(let x=0;x<800;x+=40)for(let y=0;y<480;y+=40)ctx.strokeRect(x,y,40,40);for(const e of r.enemies){const species=byId[e.speciesId]||byId.agumon;ctx.fillStyle=species.color;ctx.beginPath();const size=e.boss?30:e.type==='tank'?17:e.type==='runner'?9:12;ctx.moveTo(e.x,e.y-size);ctx.lineTo(e.x+size,e.y+size*.8);ctx.lineTo(e.x-size,e.y+size*.8);ctx.closePath();ctx.fill();if(e.phase==='aim'){ctx.save();ctx.strokeStyle='#ff6b6b';ctx.lineWidth=3;ctx.setLineDash([7,5]);ctx.beginPath();ctx.moveTo(e.x,e.y);ctx.lineTo(e.x+(p.x-e.x)*.7,e.y+(p.y-e.y)*.7);ctx.stroke();ctx.restore();}ctx.fillStyle='#fff';ctx.font='10px system-ui';ctx.textAlign='center';ctx.fillText(species.name,e.x,e.y-size-5);if(e.boss){ctx.fillStyle='#101827';ctx.fillRect(e.x-34,e.y-45,68,7);ctx.fillStyle='#f59e0b';ctx.fillRect(e.x-33,e.y-44,66*Math.max(0,e.hp/e.maxHp),5);}}for(const s of r.shots){ctx.fillStyle=s.color;ctx.beginPath();ctx.arc(s.x,s.y,5,0,Math.PI*2);ctx.fill();}for(const s of r.enemyShots){ctx.fillStyle=s.color;ctx.beginPath();ctx.arc(s.x,s.y,6,0,Math.PI*2);ctx.fill();ctx.strokeStyle='#111827';ctx.stroke();}for(const fx of r.effects){ctx.strokeStyle=fx.color;ctx.lineWidth=3;ctx.beginPath();ctx.arc(fx.x,fx.y,5+(1-fx.ttl/.22)*18,0,Math.PI*2);ctx.stroke();}ctx.fillStyle=byId[data.selected].color;ctx.save();ctx.translate(p.x,p.y);ctx.rotate(Math.sin(r.time*5)*.07);ctx.beginPath();ctx.moveTo(0,-17);ctx.lineTo(15,12);ctx.lineTo(-15,12);ctx.closePath();ctx.fill();ctx.restore();ctx.fillStyle='white';ctx.font='bold 12px system-ui';ctx.textAlign='center';ctx.fillText(byId[data.selected].name,p.x,p.y-23);$('runHud').textContent='HP '+Math.ceil(r.hp)+'/'+Math.ceil(r.maxHp)+' · KOs '+r.kills+' · Nivel '+r.level+' · '+Math.floor(r.time)+'/90s'+(r.boss?' · JEFE':'')+(r.paused?' · PAUSA':'');}
